'Original M32/OS-path teaching models. Not traces from a live kernel.'


def make(identifier, chapter, title, assumptions, labels, links, rows, marker):
    names = [item[0] for item in labels]
    steps = []
    for heading, explanation, actor, focus, active, values, field in rows:
        name, before, after, why = field
        steps.append(dict(title=heading, explanation=explanation, actor=actor,
                          focus=focus, active=active, states=dict(zip(names, values)),
                          fields=[dict(name=name, before=before, after=after, why=why)],
                          bands=[dict(label=name, value=after, detail=why)]))
    return dict(id=identifier, volume='operating-systems', chapter=chapter, anchor=chapter,
                title=title, intro=rows[0][1],
                assumptions=assumptions,
                nodes=[dict(id=i, label=label, sub=sub) for i, label, sub in labels],
                edges=[dict(id=i, **{'from':a, 'to':b}, label=label) for i,a,b,label in links],
                steps=steps, insert_before=marker)


